import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  InternalServerErrorException,
  StreamableFile,
} from '@nestjs/common';
import { Reflector } from '@nestjs/core';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Response } from 'express';
import { Buffer } from 'buffer';
import { Readable } from 'stream';
import { DOWNLOAD_FILE_KEY } from '@common/decorators/file-download.decorator';

export type ExportFormat = 'xlsx' | 'pdf' | 'csv';

export interface IDownloadResponse {
  buffer: Buffer;
  filename: string;
  format: ExportFormat;
}

@Injectable()
export class FileDownloadInterceptor implements NestInterceptor {
  private readonly mimeTypes: Record<ExportFormat, string> = {
    pdf: 'application/pdf',
    xlsx: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
    csv: 'text/csv',
  };

  constructor(private readonly reflector: Reflector) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const isDownload = this.reflector.get<boolean>(
      DOWNLOAD_FILE_KEY,
      context.getHandler(),
    );

    if (!isDownload) {
      return next.handle();
    }

    const ctx = context.switchToHttp();
    const response = ctx.getResponse<Response>();

    return next.handle().pipe(
      map((data: IDownloadResponse) => {
        if (!data || !data.buffer || !data.filename || !data.format) {
          throw new InternalServerErrorException(
            'El servicio no retornó la estructura requerida para descargas (buffer, filename, format).',
          );
        }

        const contentType =
          this.mimeTypes[data.format] || 'application/octet-stream';

        response.set({
          'Content-Disposition': `attachment; filename="${data.filename}"`,
          'Cache-Control': 'no-cache, no-store, must-revalidate',
          Pragma: 'no-cache',
          Expires: '0',
        });

        return new StreamableFile(Readable.from(data.buffer), {
          type: contentType,
          length: data.buffer.length,
        });
      }),
    );
  }
}

import { Injectable } from '@angular/core';

declare const Handlebars: any;

@Injectable({
  providedIn: 'root'
})
export class HbsRenderService {
  private handlebarsInstance: any;

  constructor() {
    this.initializeHandlebars();
  }

  private initializeHandlebars() {
    // Create a new Handlebars instance for the playground
    this.handlebarsInstance = Handlebars.create();

    // Register common helpers used in Compodoc templates
    this.registerHelpers();
  }

  private registerHelpers() {
    // Register the 'compare' helper
    this.handlebarsInstance.registerHelper('compare', (left: any, operator: string, right: any, options: any) => {
      let result;
      switch (operator) {
        case '===':
          result = left === right;
          break;
        case '!==':
          result = left !== right;
          break;
        case '<':
          result = left < right;
          break;
        case '>':
          result = left > right;
          break;
        case '<=':
          result = left <= right;
          break;
        case '>=':
          result = left >= right;
          break;
        default:
          result = false;
      }
      return result ? options.fn(this) : options.inverse(this);
    });

    // Register the 'unless' helper
    this.handlebarsInstance.registerHelper('unless', (conditional: any, options: any) => {
      return !conditional ? options.fn(this) : options.inverse(this);
    });

    // Register the 'each' helper with index
    this.handlebarsInstance.registerHelper('each', (context: any, options: any) => {
      let ret = '';
      for (let i = 0; i < context.length; i++) {
        ret += options.fn(context[i], { data: { index: i } });
      }
      return ret;
    });

    // Register the 'if' helper
    this.handlebarsInstance.registerHelper('if', (conditional: any, options: any) => {
      return conditional ? options.fn(this) : options.inverse(this);
    });

    // Register the 'relativeURL' helper
    this.handlebarsInstance.registerHelper('relativeURL', (depth: number, page?: string) => {
      let url = '';
      for (let i = 0; i < depth; i++) {
        url += '../';
      }
      return url + (page || '');
    });

    // Register the 't' helper for translations
    this.handlebarsInstance.registerHelper('t', (key: string) => {
      // Simple translation mapping for preview
      const translations: { [key: string]: string } = {
        'info': 'Information',
        'source': 'Source',
        'example': 'Example',
        'template': 'Template',
        'styles': 'Styles',
        'component': 'Component',
        'module': 'Module',
        'overview': 'Overview',
        'components': 'Components',
        'modules': 'Modules',
        'file': 'File',
        'description': 'Description',
        'selector': 'Selector',
        'properties': 'Properties',
        'methods': 'Methods',
        'inputs': 'Inputs',
        'outputs': 'Outputs'
      };
      return translations[key] || key;
    });

    // Register the 'orLength' helper
    this.handlebarsInstance.registerHelper('orLength', (...args: any[]) => {
      const options = args[args.length - 1];
      const values = args.slice(0, -1);

      for (const value of values) {
        if (value && value.length && value.length > 0) {
          return options.fn(this);
        }
      }
      return options.inverse(this);
    });

    // Register the 'isTabEnabled' helper
    this.handlebarsInstance.registerHelper('isTabEnabled', (navTabs: any[], tabId: string, options: any) => {
      const tab = navTabs && navTabs.find((t: any) => t.id === tabId);
      return tab ? options.fn(this) : options.inverse(this);
    });

    // Register the 'isInitialTab' helper
    this.handlebarsInstance.registerHelper('isInitialTab', (navTabs: any[], tabId: string, options: any) => {
      const isInitial = navTabs && navTabs.length > 0 && navTabs[0].id === tabId;
      return isInitial ? options.fn(this) : options.inverse(this);
    });
  }

  renderTemplate(templateContent: string, data: any): string {
    try {
      // Create a complete HTML document for preview
      const template = this.handlebarsInstance.compile(templateContent);
      const rendered = template({ data });

      // Wrap in a basic HTML structure for preview
      return `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <title>Template Preview</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            .preview-wrapper { border: 1px solid #ddd; padding: 20px; }
            .preview-notice { background: #f0f8ff; padding: 10px; margin-bottom: 20px; border-left: 4px solid #007bff; }
          </style>
        </head>
        <body>
          <div class="preview-notice">
            <strong>Template Preview:</strong> This is a live preview of your template with mock data.
          </div>
          <div class="preview-wrapper">
            ${rendered}
          </div>
        </body>
        </html>
      `;
    } catch (error) {
      return `
        <!DOCTYPE html>
        <html>
        <head>
          <meta charset="utf-8">
          <title>Template Preview - Error</title>
          <style>
            body { font-family: Arial, sans-serif; margin: 20px; }
            .error { color: red; background: #fff5f5; padding: 20px; border: 1px solid #red; }
          </style>
        </head>
        <body>
          <div class="error">
            <h3>Template Error</h3>
            <p><strong>Error:</strong> ${error.message}</p>
            <p>Please check your template syntax and try again.</p>
          </div>
        </body>
        </html>
      `;
    }
  }

  getMockData(): any {
    return {
      documentationMainName: 'Sample Documentation',
      depth: 0,
      context: 'component',
      components: [
        {
          name: 'SampleComponent',
          selector: 'app-sample',
          file: 'src/app/sample/sample.component.ts',
          description: 'A sample component for demonstration',
          properties: [
            { name: 'title', type: 'string', description: 'The component title' },
            { name: 'isVisible', type: 'boolean', description: 'Whether the component is visible' }
          ],
          methods: [
            { name: 'ngOnInit', description: 'Lifecycle hook', signature: 'ngOnInit(): void' },
            { name: 'onClick', description: 'Handle click events', signature: 'onClick(event: MouseEvent): void' }
          ]
        }
      ],
      navTabs: [
        { id: 'info', label: 'Info', href: '#info' },
        { id: 'source', label: 'Source', href: '#source' },
        { id: 'example', label: 'Example', href: '#example' }
      ]
    };
  }
}

import { Injectable, UnauthorizedException } from '@nestjs/common';
import { AuthGuard } from '@nestjs/passport';
import { TokenExpiredError } from 'jsonwebtoken';
import { UserWithSecurities } from '../types/user.types';

@Injectable()
export class JwtAuthGuard extends AuthGuard('jwt') {
  handleRequest<TUser = UserWithSecurities>(
    err: unknown,
    user: unknown,
    info: unknown,
  ): TUser {
    // Token expirado
    if (info instanceof TokenExpiredError) {
      throw new UnauthorizedException({
        statusCode: 401,
        message: 'Access token expired',
        error: 'Unauthorized',
        code: 'TOKEN_EXPIRED',
      });
    }

    // Token inválido / usuario inexistente
    if (err || !user) {
      throw new UnauthorizedException({
        statusCode: 401,
        message: 'Invalid access token',
        error: 'Unauthorized',
        code: 'INVALID_TOKEN',
      });
    }

    return user as TUser;
  }
}

import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { Strategy } from 'passport-jwt';
import { Request } from 'express';
import { ConfigType } from '@nestjs/config';

import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { IJwtPayload } from '@api/auth/interfaces';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { UserWithSecurities } from '@modules/auth/types/user.types';

@Injectable()
export class JwtRefreshStrategy extends PassportStrategy(
  Strategy,
  'jwt-refresh',
) {
  constructor(
    private readonly usersService: UsersDBService,
    @Inject(APP_CONFIG.KEY)
    readonly configService: ConfigType<AppConfigType>,
  ) {
    super({
      jwtFromRequest: (req: Request): string | null => {
        const token = req.cookies?.['refreshToken'];
        return typeof token === 'string' ? token : null;
      },
      passReqToCallback: false,
      ignoreExpiration: false,
      secretOrKey: configService.authentication.publicKey,
    });
  }

  async validate(payload: IJwtPayload): Promise<UserWithSecurities> {
    const user = await this.usersService.findActiveUserByEmail(payload.email);

    if (!user) {
      throw new UnauthorizedException('Usuario no encontrado o inactivo.');
    }

    return user;
  }
}

import { Inject, Injectable, UnauthorizedException } from '@nestjs/common';
import { PassportStrategy } from '@nestjs/passport';
import { ExtractJwt, Strategy } from 'passport-jwt';
import { UsersDBService } from '@modules/users-db/services/users-db.service';
import { APP_CONFIG, AppConfigType } from '@core/config/config-loader';
import { ConfigType } from '@nestjs/config';
import { IJwtPayload } from '@api/auth/interfaces';
import { UserWithSecuritiesExtended } from '../types/user.types';
import { IUserDataOnJwt } from '../interfaces/user-data-on-jwt.interface';

@Injectable()
export class JwtStrategy extends PassportStrategy(Strategy, 'jwt') {
  constructor(
    private readonly usersService: UsersDBService,
    @Inject(APP_CONFIG.KEY)
    private readonly configService: ConfigType<AppConfigType>,
  ) {
    super({
      jwtFromRequest: ExtractJwt.fromAuthHeaderAsBearerToken(),
      ignoreExpiration: false,
      secretOrKey: configService.authentication.publicKey,
    });
  }

  async validate(payload: IJwtPayload): Promise<IUserDataOnJwt> {
    const user: UserWithSecuritiesExtended | null =
      await this.usersService.findActiveUserByEmailWithPermissions(
        payload.email,
      );

    if (!user) {
      throw new UnauthorizedException();
    }

    const directPermissions = user.permissions
      .map((p) => p.permission?.name)
      .filter(Boolean);

    const rolePermissions = user.roles
      .flatMap(
        (ur) =>
          ur.role?.rolePermissions?.map((rp) => rp.permission?.name) || [],
      )
      .filter(Boolean);

    const permissions = [
      ...new Set([...directPermissions, ...rolePermissions]),
    ];

    return {
      id: user.id,
      referenceId: user.referenceId,
      email: user.email,
      firstName: user.firstName,
      lastName: user.lastName,
      currentAccessLevel: user.currentAccessLevel,
      userStatus: user.status,
      profileStatus: user.profileStatus,
      permissions: permissions,
      roles: user.roles.map((ur) => ur.role?.name).filter(Boolean),
    };
  }
}

import {
  Injectable,
  NestInterceptor,
  ExecutionContext,
  CallHandler,
  HttpStatus,
} from '@nestjs/common';
import { Observable, tap, catchError, throwError } from 'rxjs';
import { PinoLogger } from 'nestjs-pino';
import { Request } from 'express';
import { TRACE_ID_HEADER } from '@core/middlewares/trace-id.middleware';
import { formatPayload } from '@core/observability/observability.module';

@Injectable()
export class ObservabilityInterceptor implements NestInterceptor {
  constructor(private readonly logger: PinoLogger) {}

  intercept(context: ExecutionContext, next: CallHandler): Observable<any> {
    const now = Date.now();
    const ctx = context.switchToHttp();
    const req = ctx.getRequest<Request>();
    this.logger.info(
      {
        request: req?.body ? formatPayload(req?.body) : undefined,
      },
      `Incoming | ${req.method} ${req.url} | Trace ID: ${req[TRACE_ID_HEADER]}`,
    );

    return next.handle().pipe(
      tap((responseBody) => {
        const latency = Date.now() - now;
        const context = ctx.getResponse();
        const statusCode = context.statusCode;
        const statusName =
          Object.entries(HttpStatus).find(
            ([key, value]) => value === statusCode,
          )?.[0] ?? 'UNKNOWN';
        if (statusCode >= HttpStatus.OK && statusCode < HttpStatus.AMBIGUOUS) {
          this.logger.info(
            {
              response:
                responseBody != undefined
                  ? formatPayload(responseBody)
                  : undefined,
              latencyMs: latency,
            },
            `Success | ${req.method} ${req.url} - (${statusCode} - ${statusName}) | Trace ID: ${req[TRACE_ID_HEADER]}`,
          );
        } else {
          this.logger.error(
            {
              response:
                responseBody != undefined
                  ? formatPayload(responseBody)
                  : undefined,
              latencyMs: latency,
            },
            `Not OK | ${req.method} ${req.url} - (${statusCode} - ${statusName}) | Trace ID: ${req[TRACE_ID_HEADER]}`,
          );
        }
      }),
      catchError((error) => {
        const latency = Date.now() - now;
        const context = ctx.getResponse();
        const statusCode = context.statusCode;
        const statusName =
          Object.entries(HttpStatus).find(
            ([key, value]) => value === statusCode,
          )?.[0] ?? 'UNKNOWN';
        this.logger.error(
          {
            error: error.message,
            stack: error.stack,
            latencyMs: latency,
          },
          `Error | ${req.method} ${req.url} - (${statusCode} - ${statusName}) | Trace ID: ${req[TRACE_ID_HEADER]}`,
        );
        return throwError(() => error);
      }),
    );
  }
}

import { Injectable, BadRequestException } from '@nestjs/common';
import { CryptoHelper } from '@common/helpers/crypto-helpers';

import * as DTO from '@api/onboarding/dto';
import { OnboardingService } from '@modules/onboarding/services/onboarding.service';

/**
 * Servicio de API de Onboarding - Capa BFF
 *
 * Responsabilidades:
 * - Validar DTOs
 * - Desencriptar contraseñas
 * - Orquestar llamadas al OnboardingService
 * - Transformar respuestas a DTOs
 */
@Injectable()
export class OnboardingApiService {
  constructor(private readonly onboardingService: OnboardingService) {}

  /**
   * Registra un nuevo usuario (onboarding público)
   */
  async onboarding(
    dto: DTO.OnboardingUserRequestDTO,
  ): Promise<DTO.OnboardingUserResponseDTO> {
    // Desencriptar ambas contraseñas
    const decryptedPassword = CryptoHelper.decrypt(
      dto.password,
      'sha256',
    ).toString('utf-8');

    const decryptedConfirmPassword = CryptoHelper.decrypt(
      dto.confirmPassword,
      'sha256',
    ).toString('utf-8');

    // Validar que las contraseñas coincidan
    if (decryptedPassword !== decryptedConfirmPassword) {
      throw new BadRequestException('Las contraseñas no coinciden.');
    }

    // Registrar usuario con la contraseña desencriptada
    const user = await this.onboardingService.registerUser({
      firstName: dto.firstName,
      lastName: dto.lastName,
      email: dto.email,
      phoneNumber: dto.phoneNumber,
      password: decryptedPassword,
      acceptedTerms: dto.acceptTerms,
    });

    // Mapear a DTO de respuesta
    return {
      referenceId: user.referenceId,
      email: user.email,
      status: user.status,
    };
  }
}

