import {
  ValidatorConstraint,
  ValidatorConstraintInterface,
  ValidationArguments,
} from 'class-validator';

@ValidatorConstraint({ name: 'maxCommaSeparated', async: false })
export class MaxCommaSeparatedConstraint
  implements ValidatorConstraintInterface
{
  validate(value: any, args: ValidationArguments) {
    if (typeof value !== 'string') return false;

    const max = args.constraints[0];
    const rawValue = value.trim();

    if (rawValue.length === 0) return false;

    const parts = rawValue.split(',').filter((part) => part.trim().length > 0);
    return parts.length <= max;
  }

  defaultMessage(args: ValidationArguments) {
    const max = args.constraints[0];
    return `${args.property} no puede tener más de ${max} códigos separados por coma y no puede estar vacío.`;
  }
}

import {
  registerDecorator,
  ValidationOptions,
  ValidatorConstraint,
  ValidatorConstraintInterface,
  ValidationArguments,
} from 'class-validator';

@ValidatorConstraint({ name: 'notExpired', async: false })
export class NotExpiredConstraint implements ValidatorConstraintInterface {
  validate(value: string, args: ValidationArguments) {
    console.debug(`Argumentos de la validación ${JSON.stringify(args)}`);

    if (!value) return true; // Permitir nulos si el campo es opcional
    const date = new Date(value);
    const now = new Date();
    // La fecha debe ser mayor o igual a la actual
    return date.getTime() >= now.getTime();
  }

  defaultMessage(args: ValidationArguments) {
    return `${args.property} no puede ser una fecha pasada`;
  }
}

export function NotExpired(validationOptions?: ValidationOptions) {
  return function (object: object, propertyName: string) {
    registerDecorator({
      target: object.constructor,
      propertyName: propertyName,
      options: validationOptions,
      constraints: [],
      validator: NotExpiredConstraint,
    });
  };
}

