import {
  ArgumentsHost,
  Catch,
  HttpStatus,
  Logger,
  ExceptionFilter,
} from '@nestjs/common';
import { Prisma } from '@prisma/client';
import { Response } from 'express';

// CRÍTICO: Se deben agregar ambos tipos en el decorador para que NestJS los intercepte
@Catch(Prisma.PrismaClientKnownRequestError, Prisma.PrismaClientValidationError)
export class PrismaClientExceptionFilter implements ExceptionFilter {
  private readonly logger = new Logger(PrismaClientExceptionFilter.name);

  catch(
    exception:
      | Prisma.PrismaClientKnownRequestError
      | Prisma.PrismaClientValidationError,
    host: ArgumentsHost,
  ) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const message = exception.message.replace(/\n/g, '');
    const originalContext = this.extractOriginContext(exception.stack);

    // 1. Manejo de Errores Conocidos (PXXXX)
    if (exception instanceof Prisma.PrismaClientKnownRequestError) {
      this.logger.error(
        `Error en Base de Datos [${exception.code}] | Contexto: ${originalContext} | Detalle: ${message}`,
        originalContext,
      );

      switch (exception.code) {
        case 'P2002':
          return response.status(HttpStatus.CONFLICT).json({
            statusCode: HttpStatus.CONFLICT,
            message: `El registro ya existe. Campo duplicado: ${(exception?.meta?.target ?? '') as string}`,
            error: 'Conflict',
          });

        case 'P2003':
          return response.status(HttpStatus.BAD_REQUEST).json({
            statusCode: HttpStatus.BAD_REQUEST,
            message: `Error de relación. La llave foránea provista no es válida: ${(exception?.meta?.field_name ?? '') as string}`,
            error: 'Bad Request',
          });

        case 'P2021':
          return response.status(HttpStatus.SERVICE_UNAVAILABLE).json({
            statusCode: HttpStatus.SERVICE_UNAVAILABLE,
            message: 'La tabla no existe en la DB.',
            error: 'Service Unavailable',
          });

        case 'P2024':
          return response.status(HttpStatus.SERVICE_UNAVAILABLE).json({
            statusCode: HttpStatus.SERVICE_UNAVAILABLE,
            message:
              'La base de datos está experimentando una alta latencia. Intente más tarde.',
            error: 'Internal Server Error',
          });

        case 'P2025':
          return response.status(HttpStatus.NOT_FOUND).json({
            statusCode: HttpStatus.NOT_FOUND,
            message: 'El registro solicitado no existe o fue eliminado.',
            error: 'Not Found',
          });

        default:
          return response.status(HttpStatus.INTERNAL_SERVER_ERROR).json({
            statusCode: HttpStatus.INTERNAL_SERVER_ERROR,
            message: `Error interno de persistencia. Código de referencia: ${exception.code}`,
            error: 'Internal Server Error',
          });
      }
    }

    // 2. Manejo de Errores de Validación (Campos incorrectos como paymentStatus)
    if (exception instanceof Prisma.PrismaClientValidationError) {
      this.logger.error(
        `Error de Validación Prisma | Contexto: ${originalContext} | Detalle: ${message}`,
        originalContext,
      );

      const lines = exception.message.split('\n');
      const cleanMessage =
        lines.find(
          (line) =>
            line.includes('Unknown argument') || line.includes('Invalid'),
        ) ||
        'Argumentos de consulta inválidos o tipos de datos incorrectos en Prisma.';

      this.logger.error(
        `Error de Validación Prisma | Contexto: ${originalContext} | Detalle Limpio: ${cleanMessage}`,
        originalContext,
      );

      return response.status(HttpStatus.BAD_REQUEST).json({
        statusCode: HttpStatus.BAD_REQUEST,
        error: 'Bad Request',
        message: 'Error en los parámetros de consulta.',
        timestamp: new Date().toISOString(),
      });
    }
  }

  private extractOriginContext(stack?: string): string {
    if (!stack) return 'UnknownService';

    const lines = stack.split('\n');
    const appLine = lines.find(
      (line) => line.includes('.service.') && !line.includes('node_modules'),
    );

    if (appLine) {
      const match = appLine.match(/at\s+([\w.]+)\s+\(/);
      if (match && match[1]) {
        return match[1];
      }

      const fileMatch = appLine.match(/([\w-]+\.service\.[ts|js]+)/);
      if (fileMatch && fileMatch[0]) return fileMatch[0];
    }

    return 'DatabaseOperation';
  }
}

import { PaginationQueryDTO } from '@common/dtos/pagination.dto';
import { PaginationResponseDTO } from '@common/dtos/pagination.dto';
import {
  PaginationOptions,
  PrismaModelDelegate,
} from '@common/interfaces/prisma-pagination.interface';

export class PrismaPaginationUtil {
  /**
   * Pagina de forma segura resolviendo las discrepancias estructurales de las relaciones de Prisma.
   */
  static async paginate<TModel>(
    prismaModel: PrismaModelDelegate,
    query: PaginationQueryDTO & Record<string, unknown>,
    options: PaginationOptions = {},
  ): Promise<{ data: TModel[]; pagination: PaginationResponseDTO }> {
    try {
      const page = Number(query.page) || 1;
      const pageSize = Number(query.pageSize) || 10;
      const skip = (page - 1) * pageSize;

      // 1. Inicializar el WHERE combinando lo que viene explícito del Service
      const finalWhere = { ...(options.where || {}) };
      const mapping = options.fieldMapping || {};

      // 2. Extraer y mapear filtros directos del DTO (status, type, etc.)
      const infrastructureKeys = [
        'page',
        'pageSize',
        'orderBy',
        'startDate',
        'endDate',
        'branches',
        'search',
      ];

      Object.keys(query).forEach((key) => {
        if (
          !infrastructureKeys.includes(key) &&
          query[key] !== undefined &&
          query[key] !== null &&
          query[key] !== ''
        ) {
          const targetKey = mapping[key] !== undefined ? mapping[key] : key;

          if (targetKey === '') {
            return;
          }

          finalWhere[targetKey] = query[key];
        }
      });

      // 3. Búsqueda multi-palabra (AND de ORs sobre los campos indicados)
      if (
        typeof query.search === 'string' &&
        query.search &&
        options.searchFields?.length
      ) {
        const words = query.search.trim().split(/\s+/).filter(Boolean);

        if (words.length > 0) {
          finalWhere.AND = words.map((word) => ({
            OR: options.searchFields!.map((field) => ({
              [field]: { contains: word, mode: 'insensitive' },
            })),
          }));
        }
      }

      // 4. Rangos de Fecha
      const dateFilter =
        (finalWhere.createdAt as Record<string, unknown>) || {};
      if (query.startDate || query.endDate) {
        if (query.startDate) dateFilter.gte = query.startDate;
        if (query.endDate) dateFilter.lte = query.endDate;
      }
      if (Object.keys(dateFilter).length > 0) {
        finalWhere.createdAt = dateFilter;
      }

      // 5. Sucursales Múltiples
      if (query.branches) {
        const branchArray = query.branches.split(',').map((b) => b.trim());
        finalWhere.branchCode = { in: branchArray };
      }

      // 6. Parseo de ordenamiento (campo:dirección)
      let orderBy: Record<string, 'asc' | 'desc'> = {
        [options.defaultOrderByField || 'createdAt']: 'desc',
      };

      if (typeof query.orderBy === 'string' && query.orderBy.includes(':')) {
        const [field, direction] = query.orderBy.split(':');
        const targetOrderField = mapping[field] || field;
        if (field && direction) {
          orderBy = {
            [targetOrderField]: direction.toLowerCase() as 'asc' | 'desc',
          };
        }
      }

      // 7. Consulta concurrente
      const [items, rawTotal] = await Promise.all([
        prismaModel.findMany({
          where: finalWhere,
          include: options.include,
          skip,
          take: pageSize,
          orderBy,
        }),
        prismaModel.count({
          where: finalWhere,
        }),
      ]);

      const total = typeof rawTotal === 'number' ? rawTotal : 0;
      const totalPages = Math.ceil(total / pageSize);

      // Forzamos el casteo de la lista plana al modelo tipado final de salida con relaciones
      const typedData = items as unknown as TModel[];

      return {
        data: typedData,
        pagination: {
          total,
          page,
          pageSize,
          totalPages,
        },
      };
    } catch (error) {
      console.error('Error en paginación de Prisma:', error);
      throw error;
    }
  }
}

import { StorageExecutionOptions } from '@modules/storage/interfaces/storage.interface';
import {
  ServiceUnavailableException,
  BadRequestException,
} from '@nestjs/common';

export class ProcessBatchManager {
  async executeWithRetry<T>(
    operation: () => Promise<T>,
    executionOptions?: StorageExecutionOptions,
  ): Promise<T> {
    const retryAttempts = this.resolveRetryAttempts(
      executionOptions?.retryAttempts,
    );
    const retryDelayMs = this.resolveRetryDelayMs(
      executionOptions?.retryDelayMs,
    );

    for (let attempt = 0; attempt <= retryAttempts; attempt += 1) {
      try {
        return await operation();
      } catch (error) {
        if (attempt === retryAttempts || !this.shouldRetry(error)) {
          throw error;
        }

        await this.delay(retryDelayMs * (attempt + 1));
      }
    }

    throw new ServiceUnavailableException(
      'Storage service is temporarily unavailable',
    );
  }

  private shouldRetry(error: unknown): boolean {
    const errorName =
      error && typeof error === 'object' && 'name' in error
        ? String(error.name)
        : '';
    const statusCode =
      error && typeof error === 'object' && '$metadata' in error
        ? Number(
            (error as { $metadata?: { httpStatusCode?: number } }).$metadata
              ?.httpStatusCode,
          )
        : undefined;

    return (
      errorName === 'SlowDown' ||
      errorName === 'Throttling' ||
      errorName === 'TooManyRequestsException' ||
      statusCode === 429 ||
      statusCode === 503
    );
  }

  async processInBatches<T, TResult>(
    items: T[],
    batchSize: number,
    handler: (item: T) => Promise<TResult>,
  ): Promise<TResult[]> {
    const results: TResult[] = [];

    for (let index = 0; index < items.length; index += batchSize) {
      const batch = items.slice(index, index + batchSize);
      const batchResults = await Promise.all(
        batch.map((item) => handler(item)),
      );
      results.push(...batchResults);
    }

    return results;
  }

  private resolveRetryAttempts(value?: number): number {
    const retryAttempts: number = value ?? 3;

    if (!Number.isInteger(retryAttempts) || retryAttempts < 0) {
      throw new BadRequestException('retryAttempts must be 0 or greater');
    }

    return retryAttempts;
  }

  private resolveRetryDelayMs(value?: number): number {
    const retryDelayMs: number = value ?? 1000;

    if (!Number.isInteger(retryDelayMs) || retryDelayMs < 0) {
      throw new BadRequestException('retryDelayMs must be 0 or greater');
    }

    return retryDelayMs;
  }

  private async delay(milliseconds: number): Promise<void> {
    await new Promise((resolve) => setTimeout(resolve, milliseconds));
  }
}

